from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext


CENT = Decimal("0.01")
BULK_FACTOR = Decimal("0.85")
LOYALTY_FACTOR = Decimal("0.95")
FREE_SHIPPING_THRESHOLD = Decimal("50.00")
STANDARD_SHIPPING = Decimal("5.99")

LOYALTY_START = date(2026, 5, 25)
TAX_RATE_CHANGE = date(2026, 7, 1)

VALID_CATEGORIES = {"standard", "clearance", "gift_card", "digital"}
DISCOUNTABLE_CATEGORIES = {"standard", "digital"}


def price_order(order: dict) -> dict:
    """
    order = {
        "date": "2026-07-15",          # ISO date the order was placed
        "member": True,                # loyalty member or not
        "items": [
            {"sku": "A1", "category": "standard", "qty": 3, "unit_price": "19.99"},
        ],
    }
    category is one of: "standard", "clearance", "gift_card", "digital".
    unit_price is a decimal string.

    Return {"subtotal", "discount", "tax", "shipping", "total"} as decimal.Decimal
    values with exactly two decimal places. "discount" is a positive amount taken off.
    """
    if not isinstance(order, dict):
        raise TypeError("order must be a dictionary")

    try:
        date_string = order["date"]
        member = order["member"]
        items = order["items"]
    except KeyError as exc:
        raise ValueError(f"missing order field: {exc.args[0]}") from exc

    if not isinstance(date_string, str):
        raise TypeError("date must be an ISO date string")

    try:
        order_date = date.fromisoformat(date_string)
    except ValueError as exc:
        raise ValueError("date must be a valid YYYY-MM-DD ISO date") from exc

    if order_date.isoformat() != date_string:
        raise ValueError("date must be in YYYY-MM-DD format")

    if not isinstance(member, bool):
        raise TypeError("member must be a boolean")

    if not isinstance(items, list):
        raise TypeError("items must be a list")

    parsed_items = []
    required_precision = 28

    for item in items:
        if not isinstance(item, dict):
            raise TypeError("each item must be a dictionary")

        try:
            category = item["category"]
            qty = item["qty"]
            unit_price_value = item["unit_price"]
        except KeyError as exc:
            raise ValueError(f"missing item field: {exc.args[0]}") from exc

        if category not in VALID_CATEGORIES:
            raise ValueError(f"unknown category: {category!r}")

        if type(qty) is not int:
            raise TypeError("qty must be an integer")

        if qty < 0:
            raise ValueError("qty must not be negative")

        if not isinstance(unit_price_value, str):
            raise TypeError("unit_price must be a decimal string")

        try:
            unit_price = Decimal(unit_price_value)
        except InvalidOperation as exc:
            raise ValueError("unit_price must be a valid decimal string") from exc

        if not unit_price.is_finite():
            raise ValueError("unit_price must be finite")

        if unit_price < 0:
            raise ValueError("unit_price must not be negative")

        if unit_price.as_tuple().exponent < -2:
            raise ValueError("unit_price must be cent-denominated")

        integer_digits = max(1, unit_price.adjusted() + 1)
        required_precision = max(
            required_precision,
            integer_digits + len(str(qty)) + len(str(len(items) + 1)) + 12,
        )

        parsed_items.append((category, qty, unit_price))

    with localcontext() as context:
        context.prec = required_precision

        subtotal = Decimal("0")
        taxable_subtotal = Decimal("0")
        raw_discount = Decimal("0")

        loyalty_applies = member is True and order_date >= LOYALTY_START

        for category, qty, unit_price in parsed_items:
            line_amount = Decimal(qty) * unit_price
            subtotal += line_amount

            if category != "gift_card":
                taxable_subtotal += line_amount

            if category not in DISCOUNTABLE_CATEGORIES:
                continue

            discounted_line_amount = line_amount

            if qty >= 100:
                discounted_line_amount *= BULK_FACTOR

            if loyalty_applies:
                discounted_line_amount *= LOYALTY_FACTOR

            raw_discount += line_amount - discounted_line_amount

        discount = raw_discount.quantize(CENT, rounding=ROUND_HALF_UP)

        taxable_net = taxable_subtotal - discount
        tax_rate = Decimal("0.08") if order_date < TAX_RATE_CHANGE else Decimal("0.10")
        tax = (taxable_net * tax_rate).quantize(CENT, rounding=ROUND_HALF_UP)

        net_merchandise = subtotal - discount
        digital_only = all(category == "digital" for category, _, _ in parsed_items)

        if digital_only or net_merchandise >= FREE_SHIPPING_THRESHOLD:
            shipping = Decimal("0.00")
        else:
            shipping = STANDARD_SHIPPING

        subtotal = subtotal.quantize(CENT, rounding=ROUND_HALF_UP)
        shipping = shipping.quantize(CENT, rounding=ROUND_HALF_UP)
        total = (subtotal - discount + tax + shipping).quantize(
            CENT, rounding=ROUND_HALF_UP
        )

        return {
            "subtotal": subtotal,
            "discount": discount,
            "tax": tax,
            "shipping": shipping,
            "total": total,
        }
